// Browser Web Push bridge. Unlike native shells, a PWA must obtain Notification permission from an
// explicit settings action, then create a PushManager subscription with the server's public VAPID key.
import type { PushBridge, PushData, PushToken } from "../../core/src/push.ts";

interface SubscriptionLike {
  endpoint: string;
  getKey(name: "p256dh" | "auth"): ArrayBuffer | null;
  unsubscribe(): Promise<boolean>;
}

interface PushManagerLike {
  getSubscription(): Promise<SubscriptionLike | null>;
  subscribe(options: { userVisibleOnly: true; applicationServerKey: Uint8Array }): Promise<SubscriptionLike>;
}

interface RegistrationLike {
  pushManager: PushManagerLike;
}

export interface WebPushEnv {
  supported(): boolean;
  permission(): string;
  requestPermission(): Promise<string>;
  registration(): Promise<RegistrationLike>;

  enabledPreference(): boolean | null;
  setEnabledPreference(enabled: boolean): void;
  setBadge(count: number): void;
}

export interface WebPushController {
  readonly supported: boolean;
  readonly bridge: PushBridge;
  readonly settings: {
    getNotifications(): Promise<boolean>;
    setNotifications(enabled: boolean): Promise<void>;
  };
  setVapidPublicKey(key: unknown): void;
}

function decodeBase64Url(value: string): Uint8Array {
  const padded = value.replace(/-/g, "+").replace(/_/g, "/") + "=".repeat((4 - value.length % 4) % 4);
  const raw = atob(padded);
  const out = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i += 1) out[i] = raw.charCodeAt(i);
  return out;
}

function encodeBase64Url(value: ArrayBuffer | null): string | null {
  if (!value) return null;
  const bytes = new Uint8Array(value);
  let raw = "";
  for (let i = 0; i < bytes.length; i += 1) raw += String.fromCharCode(bytes[i]!);
  return btoa(raw).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function tokenFromSubscription(subscription: SubscriptionLike): PushToken | null {
  const p256dh = encodeBase64Url(subscription.getKey("p256dh"));
  const auth = encodeBase64Url(subscription.getKey("auth"));
  if (!subscription.endpoint || !p256dh || !auth) return null;
  return { platform: "webpush", endpoint: subscription.endpoint, keys: { p256dh, auth } };
}

function sameToken(a: PushToken | null, b: PushToken | null): boolean {
  return a === b || (
    a !== null && b !== null && a.endpoint === b.endpoint &&
    a.keys?.p256dh === b.keys?.p256dh && a.keys?.auth === b.keys?.auth
  );
}

export function createWebPushController(env: WebPushEnv): WebPushController {
  const supported = env.supported();
  const tokenListeners = new Set<(token: PushToken | null) => void>();
  const pushListeners = new Set<(data: PushData) => void>();
  let vapidKey: string | null = null;
  let current: PushToken | null = null;
  let serial = Promise.resolve();

  const run = <T>(operation: () => Promise<T>): Promise<T> => {
    const next = serial.then(operation, operation);
    serial = next.then(() => undefined, () => undefined);
    return next;
  };
  const emit = (token: PushToken | null): void => {
    if (sameToken(current, token)) return;
    current = token;
    for (const cb of [...tokenListeners]) {
      try { cb(token); } catch { /* one observer must not break registration */ }
    }
  };

  const refresh = async (createIfMissing: boolean): Promise<PushToken | null> => {
    if (env.enabledPreference() === false || !supported || !vapidKey || env.permission() !== "granted") {
      emit(null);
      return null;
    }
    const registration = await env.registration();
    let subscription = await registration.pushManager.getSubscription();
    if (!subscription && createIfMissing) {
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: decodeBase64Url(vapidKey),
      });
    }
    const token = subscription ? tokenFromSubscription(subscription) : null;
    emit(token);
    return token;
  };

  const bridge: PushBridge = {
    getToken: () => run(() => refresh(true)).catch(() => null),
    onToken: (cb) => {
      tokenListeners.add(cb);
      return () => { tokenListeners.delete(cb); };
    },
    onPush: (cb) => {
      // Background pushes are rendered by sw.js. This hook remains for interface parity/possible future
      // postMessage delivery while the page is foregrounded.
      pushListeners.add(cb);
      return () => { pushListeners.delete(cb); };
    },
    setBadge: (count) => env.setBadge(Math.max(0, Math.trunc(count))),
  };

  return {
    supported,
    bridge,
    settings: {
      getNotifications: () => run(async () => (await refresh(false)) !== null).catch(() => false),
      setNotifications: (enabled) => run(async () => {
        if (!supported) throw new Error("Web Push is not supported by this browser");
        if (!enabled) {
          env.setEnabledPreference(false);
          const registration = await env.registration();
          const subscription = await registration.pushManager.getSubscription();
          if (subscription) await subscription.unsubscribe();
          emit(null);
          return;
        }
        if (!vapidKey) throw new Error("Web Push is not configured on the server");
        const permission = env.permission() === "granted" ? "granted" : await env.requestPermission();
        if (permission !== "granted") {
          env.setEnabledPreference(false);
          throw new Error("Notification permission was not granted");
        }
        env.setEnabledPreference(true);
        const token = await refresh(true);
        if (!token) throw new Error("Browser push subscription could not be created");
      }),
    },
    setVapidPublicKey(key) {
      const next = typeof key === "string" && key.trim().length > 0 ? key.trim() : null;
      if (next === vapidKey) return;
      vapidKey = next;
      const mayCreate = env.permission() === "granted" && env.enabledPreference() !== false;
      void run(() => refresh(mayCreate)).catch(() => emit(null));
    },
  };
}

export function browserWebPushEnv(): WebPushEnv {
  const enabledKey = "gc.webpush.enabled";
  const supported = (): boolean => typeof window !== "undefined" && typeof navigator !== "undefined" &&
    "serviceWorker" in navigator && typeof Notification !== "undefined" && typeof PushManager !== "undefined";
  return {
    supported,
    permission: () => (typeof Notification !== "undefined" ? Notification.permission : "denied"),
    requestPermission: () => Notification.requestPermission(),
    registration: async () => {
      if (!supported()) throw new Error("Web Push unsupported");
      const timeout = new Promise<never>((_resolve, reject) => {
        setTimeout(() => reject(new Error("Service Worker registration is unavailable")), 10_000);
      });
      return (await Promise.race([navigator.serviceWorker.ready, timeout])) as unknown as RegistrationLike;
    },
    enabledPreference: () => {
      try {
        const value = localStorage.getItem(enabledKey);
        return value === "1" ? true : value === "0" ? false : null;
      } catch { return null; }
    },
    setEnabledPreference(enabled) {
      try { localStorage.setItem(enabledKey, enabled ? "1" : "0"); } catch { /* storage may be blocked */ }
    },
    setBadge(count) {
      const nav = navigator as Navigator & {
        setAppBadge?: (count?: number) => Promise<void>;
        clearAppBadge?: () => Promise<void>;
      };
      try {
        if (count > 0 && typeof nav.setAppBadge === "function") void nav.setAppBadge(count).catch(() => undefined);
        else if (typeof nav.clearAppBadge === "function") void nav.clearAppBadge().catch(() => undefined);
      } catch { /* optional browser API */ }
    },
  };
}

export function createBrowserWebPushController(): WebPushController {
  return createWebPushController(browserWebPushEnv());
}
